WITH filtered AS (SELECT id, customer_id, order_date, channel, amount, discount, shipping_fee, LENGTH(status) AS status_length FROM orders WHERE MONTH(order_date) IN (1, 2, 4)), not_flagged AS (SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM order_items ch WHERE ch.order_id = s.id AND ch.quantity <= 4)), ranked AS (SELECT *, RANK() OVER (PARTITION BY channel ORDER BY amount DESC NULLS LAST) AS dedup_rank FROM not_flagged QUALIFY dedup_rank = 1), enriched AS (SELECT s.id, s.customer_id, s.channel, s.status_length, c.country, c.signup_date, c.email FROM ranked s LEFT JOIN customers c ON s.customer_id = c.id WHERE c.country NOT IN ('UK', 'DE', 'SG')) SELECT s.id, s.customer_id, s.signup_date, s.email, (SELECT MIN(o2.amount) FROM orders o2 WHERE o2.customer_id = s.customer_id) AS min_order_amount FROM enriched s ORDER BY id NULLS FIRST;
